["-- Card families include their purpose-specific actions. Event, restaurant and
-- review cards therefore carry venue + primary-link fields at every tier.
CREATE OR REPLACE FUNCTION public.tap_card_features(p_tap UUID)
RETURNS TEXT[] LANGUAGE SQL STABLE SECURITY DEFINER
SET search_path = public, pg_temp AS $$
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM public.cards c WHERE c.tap_profile_id=p_tap AND c.status <> 'replaced' AND (c.sku LIKE 'card-event-%' OR c.sku LIKE 'card-restaurant-%')) THEN ARRAY['location','website','links']::TEXT[]
    WHEN EXISTS (SELECT 1 FROM public.cards c WHERE c.tap_profile_id=p_tap AND c.status <> 'replaced' AND c.sku LIKE 'card-google-review-%') THEN ARRAY['location','website']::TEXT[]
    ELSE ARRAY[]::TEXT[]
  END;
$$;
REVOKE ALL ON FUNCTION public.tap_card_features(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.tap_card_features(UUID) TO anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.enforce_tap_edit_rules()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp AS $$
DECLARE v_tier TEXT; v_pass BOOLEAN; v_owned TEXT[]; v_content BOOLEAN;
BEGIN
  IF auth.uid() IS NULL OR NEW.user_id IS DISTINCT FROM auth.uid() THEN RETURN NEW; END IF;
  v_tier := public.user_max_ui_tier(NEW.user_id);
  v_pass := public.user_has_pass(NEW.user_id);
  NEW.enabled_customizations := ARRAY(SELECT DISTINCT value
    FROM unnest(COALESCE(NEW.enabled_customizations,'{}'::text[]) || ARRAY['phone','email']) AS u(value)
    WHERE value <> '' ORDER BY value);
  IF public.tier_rank(NEW.selected_ui_tier) > public.tier_rank(v_tier) THEN
    RAISE EXCEPTION 'You have not purchased the % experience.', NEW.selected_ui_tier USING ERRCODE='42501';
  END IF;
  IF NEW.theme_palette <> ALL(public.theme_options('palette',v_tier,v_pass)) THEN RAISE EXCEPTION 'That colour palette is not unlocked on your plan.' USING ERRCODE='42501'; END IF;
  IF NEW.theme_layout <> ALL(public.theme_options('layout',v_tier,v_pass)) THEN RAISE EXCEPTION 'That layout is not unlocked on your plan.' USING ERRCODE='42501'; END IF;
  IF NEW.theme_buttons <> ALL(public.theme_options('buttons',v_tier,v_pass)) THEN RAISE EXCEPTION 'That button style is not unlocked on your plan.' USING ERRCODE='42501'; END IF;
  IF NEW.theme_font <> ALL(public.theme_options('font',v_tier,v_pass)) THEN RAISE EXCEPTION 'That font is not unlocked on your plan.' USING ERRCODE='42501'; END IF;
  IF NEW.theme_animation <> ALL(public.theme_options('animation',v_tier,v_pass)) THEN RAISE EXCEPTION 'That animation style is not unlocked on your plan.' USING ERRCODE='42501'; END IF;
  SELECT COALESCE(array_agg(e.key),'{}') INTO v_owned FROM public.entitlements e
    WHERE e.user_id=NEW.user_id AND e.is_active AND e.type='customization';
  v_owned := v_owned || public.tap_card_features(NEW.id);
  IF EXISTS(SELECT 1 FROM unnest(NEW.enabled_customizations) AS k(key)
    WHERE k.key <> ALL(v_owned || public.tier_buttons(NEW.selected_ui_tier))) THEN
    RAISE EXCEPTION 'That add-on has not been purchased.' USING ERRCODE='42501';
  END IF;
  v_content := NEW.display_name IS DISTINCT FROM OLD.display_name OR NEW.headline IS DISTINCT FROM OLD.headline
    OR NEW.designation IS DISTINCT FROM OLD.designation OR NEW.company IS DISTINCT FROM OLD.company
    OR NEW.bio IS DISTINCT FROM OLD.bio OR NEW.avatar_url IS DISTINCT FROM OLD.avatar_url
    OR NEW.location IS DISTINCT FROM OLD.location OR NEW.phone IS DISTINCT FROM OLD.phone
    OR NEW.whatsapp IS DISTINCT FROM OLD.whatsapp OR NEW.email IS DISTINCT FROM OLD.email
    OR NEW.website IS DISTINCT FROM OLD.website OR NEW.instagram IS DISTINCT FROM OLD.instagram
    OR NEW.linkedin IS DISTINCT FROM OLD.linkedin OR NEW.youtube IS DISTINCT FROM OLD.youtube
    OR NEW.custom_links IS DISTINCT FROM OLD.custom_links OR NEW.theme_palette IS DISTINCT FROM OLD.theme_palette
    OR NEW.theme_layout IS DISTINCT FROM OLD.theme_layout OR NEW.theme_buttons IS DISTINCT FROM OLD.theme_buttons
    OR NEW.theme_font IS DISTINCT FROM OLD.theme_font OR NEW.theme_animation IS DISTINCT FROM OLD.theme_animation
    OR (NEW.slug IS DISTINCT FROM OLD.slug AND OLD.slug IS NOT NULL);
  IF NOT v_content THEN RETURN NEW; END IF;
  IF cardinality(public.tap_card_features(NEW.id)) = 0
     AND NOT (v_pass OR OLD.last_content_edit_at IS NULL OR OLD.last_content_edit_at + make_interval(days => public.tap_edit_interval_days()) <= NOW()) THEN
    RAISE EXCEPTION 'You can change your Tap once every % days. The Customization Pass removes the limit.', public.tap_edit_interval_days() USING ERRCODE='42501';
  END IF;
  NEW.last_content_edit_at := NOW(); RETURN NEW;
END;
$$;

-- Purpose-built pages need timely edits to dates, hours, addresses, menus,
-- and RSVP/review links. Keep the normal edit limit for personal/business pages.
CREATE OR REPLACE FUNCTION public.tap_page_edit_state(p_tap_id UUID)
RETURNS TABLE(last_edit_at TIMESTAMPTZ, next_edit_at TIMESTAMPTZ, days_remaining INT,
              interval_days INT, has_pass BOOLEAN, can_edit BOOLEAN, reason TEXT)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE v_user UUID := auth.uid(); v_last TIMESTAMPTZ; v_next TIMESTAMPTZ;
        v_pass BOOLEAN; v_found BOOLEAN := false; v_family BOOLEAN := false;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE='42501'; END IF;
  SELECT t.last_content_edit_at, true INTO v_last, v_found
  FROM public.tap_profiles t WHERE t.id=p_tap_id AND t.user_id=v_user;
  IF v_found THEN v_family := cardinality(public.tap_card_features(p_tap_id)) > 0; END IF;
  v_pass := public.user_has_pass(v_user);
  v_next := v_last + make_interval(days => public.tap_edit_interval_days());
  RETURN QUERY SELECT v_last,
    CASE WHEN v_pass OR v_family THEN NULL ELSE v_next END,
    CASE WHEN v_pass OR v_family OR v_next IS NULL THEN 0
         ELSE GREATEST(0, CEIL(EXTRACT(EPOCH FROM (v_next-NOW()))/86400.0))::INT END,
    public.tap_edit_interval_days(), v_pass,
    CASE WHEN NOT COALESCE(v_found,false) THEN false WHEN v_pass OR v_family THEN true
         WHEN v_next IS NULL THEN true ELSE v_next <= NOW() END,
    CASE WHEN NOT COALESCE(v_found,false) THEN 'no_tap' WHEN v_family THEN 'card_family'
         WHEN v_pass THEN 'pass' WHEN v_next IS NULL THEN 'never_edited'
         WHEN v_next <= NOW() THEN 'edit_available' ELSE 'cooling_down' END;
END;
$$;
REVOKE ALL ON FUNCTION public.tap_page_edit_state(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.tap_page_edit_state(UUID) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_public_profile(p_slug TEXT)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp AS $$
DECLARE
  v_tap public.tap_profiles%ROWTYPE;
  v_tier TEXT; v_pass BOOLEAN; v_owned TEXT[]; v_shown TEXT[]; v_clamp TEXT;
  v_event JSONB; v_event_theme JSONB; v_base JSONB; v_eff JSONB;
BEGIN
  SELECT * INTO v_tap FROM public.tap_profiles t
  WHERE lower(t.slug) = lower(btrim(COALESCE(p_slug, '')))
    AND t.status = 'active' AND t.suspended_at IS NULL LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;
  v_tier := public.user_max_ui_tier(v_tap.user_id);
  v_pass := public.user_has_pass(v_tap.user_id);
  SELECT COALESCE(array_agg(e.key), '{}') INTO v_owned FROM public.entitlements e
  WHERE e.user_id = v_tap.user_id AND e.is_active AND e.type = 'customization';
  v_clamp := CASE WHEN public.tier_rank(v_tap.selected_ui_tier) <= public.tier_rank(v_tier)
    THEN public.canonical_experience(v_tap.selected_ui_tier) ELSE v_tier END;
  v_shown := ARRAY(SELECT unnest(v_tap.enabled_customizations)
    INTERSECT SELECT unnest(v_owned || public.tier_buttons(v_clamp) || public.tap_card_features(v_tap.id)));
  v_base := jsonb_build_object(
    'palette', CASE WHEN v_tap.theme_palette = ANY(public.theme_options('palette',v_clamp,v_pass)) THEN v_tap.theme_palette ELSE 'midnight' END,
    'layout', CASE WHEN v_tap.theme_layout = ANY(public.theme_options('layout',v_clamp,v_pass)) THEN v_tap.theme_layout ELSE 'classic' END,
    'buttons', CASE WHEN v_tap.theme_buttons = ANY(public.theme_options('buttons',v_clamp,v_pass)) THEN v_tap.theme_buttons ELSE 'solid' END,
    'font', CASE WHEN v_tap.theme_font = ANY(public.theme_options('font',v_clamp,v_pass)) THEN v_tap.theme_font ELSE 'sans' END,
    'animation', CASE WHEN v_tap.theme_animation = ANY(public.theme_options('animation',v_clamp,v_pass)) THEN v_tap.theme_animation ELSE 'auto' END);
  v_event := public.tap_event_theme_for(now());
  v_event_theme := COALESCE(v_event->'theme','{}'::jsonb);
  v_eff := jsonb_build_object(
    'palette',COALESCE(NULLIF(v_event_theme->>'palette',''),v_base->>'palette'),
    'layout',COALESCE(NULLIF(v_event_theme->>'layout',''),v_base->>'layout'),
    'buttons',COALESCE(NULLIF(v_event_theme->>'buttons',''),v_base->>'buttons'),
    'font',COALESCE(NULLIF(v_event_theme->>'font',''),v_base->>'font'),
    'animation',COALESCE(NULLIF(v_event_theme->>'animation',''),v_base->>'animation'));
  RETURN jsonb_build_object(
    'slug',v_tap.slug,'experience',v_clamp,'displayName',v_tap.display_name,'headline',v_tap.headline,
    'designation',v_tap.designation,'company',v_tap.company,'bio',v_tap.bio,'avatarUrl',v_tap.avatar_url,
    'location',CASE WHEN 'location'=ANY(v_shown) THEN v_tap.location END,
    'phone',CASE WHEN 'phone'=ANY(v_shown) THEN v_tap.phone END,
    'whatsapp',CASE WHEN 'whatsapp'=ANY(v_shown) THEN v_tap.whatsapp END,
    'email',CASE WHEN 'email'=ANY(v_shown) THEN v_tap.email END,
    'website',CASE WHEN 'website'=ANY(v_shown) THEN v_tap.website END,
    'instagram',CASE WHEN 'instagram'=ANY(v_shown) THEN v_tap.instagram END,
    'linkedin',CASE WHEN 'linkedin'=ANY(v_shown) THEN v_tap.linkedin END,
    'youtube',CASE WHEN 'youtube'=ANY(v_shown) THEN v_tap.youtube END,
    'customLinks',CASE WHEN 'links'=ANY(v_shown) THEN v_tap.custom_links ELSE '[]'::jsonb END,
    'theme',v_eff,'baseTheme',v_base,'activeEvent',NULLIF(v_event,'{}'::jsonb));
END;
$$;
REVOKE ALL ON FUNCTION public.get_public_profile(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_public_profile(TEXT) TO anon;
REVOKE EXECUTE ON FUNCTION public.get_public_profile(TEXT) FROM authenticated;

"]

["-- Page families are independent of visual layout and physical card finish.
ALTER TABLE public.tap_profiles
  ADD COLUMN IF NOT EXISTS page_template TEXT
  CHECK (page_template IS NULL OR page_template IN ('business', 'restaurant', 'event', 'review'));

-- Let an authorised SHYGON administrator create an additional Tap page for an
-- existing customer. The customer owns and edits the page after creation.
-- A draft is used so an empty page is not published before the customer fills it.

-- Stop offering card finishes and add-ons the current website cannot sell.
-- Rows remain for references from old orders and reports.
UPDATE public.products
SET active = false
WHERE product_type = 'card'
  AND material = 'transparent'
  AND active IS DISTINCT FROM false;

UPDATE public.products
SET active = false
WHERE sku IN ('plan-pro', 'plan-3d', 'plan-custom', 'plan-lifetime', 'addon-gallery')
  AND active IS DISTINCT FROM false;

DROP FUNCTION IF EXISTS public.admin_create_tap_page(UUID, TEXT, TEXT, TEXT, TEXT);
CREATE FUNCTION public.admin_create_tap_page(
  p_user_id UUID,
  p_display_name TEXT,
  p_slug TEXT,
  p_page_template TEXT,
  p_layout TEXT,
  p_headline TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_admin UUID := public.require_admin('tap.moderate');
  v_name TEXT := NULLIF(btrim(COALESCE(p_display_name, '')), '');
  v_slug TEXT := lower(btrim(COALESCE(p_slug, '')));
  v_headline TEXT := NULLIF(btrim(COALESCE(p_headline, '')), '');
  v_tier TEXT;
  v_id UUID;
BEGIN
  IF p_user_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'Choose an existing customer.' USING ERRCODE = 'P0002';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id AND suspended_at IS NOT NULL) THEN
    RAISE EXCEPTION 'A Tap page cannot be created for a suspended customer.' USING ERRCODE = '22023';
  END IF;
  IF v_name IS NULL OR length(v_name) > 60 THEN
    RAISE EXCEPTION 'Enter a page name of 1–60 characters.' USING ERRCODE = '22023';
  END IF;
  IF v_headline IS NOT NULL AND length(v_headline) > 120 THEN
    RAISE EXCEPTION 'The short introduction must be 120 characters or fewer.' USING ERRCODE = '22023';
  END IF;
  IF v_slug !~ '^[a-z0-9][a-z0-9-]{2,39}$' THEN
    RAISE EXCEPTION 'The page address must be 3–40 lowercase letters, numbers, or hyphens.' USING ERRCODE = '22023';
  END IF;
  IF public.tap_slug_reserved(v_slug) THEN
    RAISE EXCEPTION 'That page address is reserved.' USING ERRCODE = '22023';
  END IF;
  IF public.tap_slug_taken(v_slug) THEN
    RAISE EXCEPTION 'That page address is already in use.' USING ERRCODE = '23505';
  END IF;

  v_tier := COALESCE(public.user_max_ui_tier(p_user_id), 'essential');
  IF p_page_template IS NULL OR p_page_template NOT IN ('business', 'restaurant', 'event', 'review') THEN
    RAISE EXCEPTION 'Choose a valid page template.' USING ERRCODE = '22023';
  END IF;
  IF p_layout IS NULL OR p_layout <> ALL (public.theme_options('layout', v_tier, public.user_has_pass(p_user_id))) THEN
    RAISE EXCEPTION 'This template is not available for the customer’s current Tap experience.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.tap_profiles (
    user_id, customer_id, slug, username, display_name, headline, email,
    status, published, published_at, selected_ui_tier, enabled_customizations,
    theme_layout, theme_palette, theme_buttons, theme_font, theme_animation, page_template
  )
  SELECT p.id, p.id, v_slug, v_slug, v_name, v_headline, p.email,
         'draft', false, NULL, v_tier, ARRAY[]::TEXT[], p_layout,
         'midnight', 'solid', 'sans', 'auto', p_page_template
  FROM public.profiles p
  WHERE p.id = p_user_id
  RETURNING id INTO v_id;

  INSERT INTO public.notifications (user_id, category, title, body, link, metadata)
  VALUES (
    p_user_id,
    'tap',
    'A new Tap page is ready to edit',
    'Your new page “' || v_name || '” is a draft. Add your details and publish it from your profile.',
    '/shygontap/tap',
    jsonb_build_object('tap_profile_id', v_id, 'slug', v_slug)
  );

  PERFORM public.admin_audit(
    v_admin,
    'tap.page_created',
    'tap',
    v_id::text,
    jsonb_build_object('user_id', p_user_id, 'slug', v_slug, 'page_template', p_page_template, 'layout', p_layout)
  );

  RETURN public.admin_get_tap(v_id);
END;
$$;

REVOKE ALL ON FUNCTION public.admin_create_tap_page(UUID, TEXT, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_create_tap_page(UUID, TEXT, TEXT, TEXT, TEXT, TEXT) TO authenticated, service_role;


-- Public renderer receives the selected page family through the existing
-- entitlement-clamped profile resolver.
CREATE OR REPLACE FUNCTION public.get_public_profile(p_slug TEXT)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_tap         public.tap_profiles%ROWTYPE;
  v_tier        TEXT;
  v_pass        BOOLEAN;
  v_owned       TEXT[];
  v_shown       TEXT[];
  v_clamp       TEXT;
  v_event       JSONB;
  v_event_theme JSONB;
  v_base        JSONB;
  v_eff         JSONB;
BEGIN
  SELECT * INTO v_tap
  FROM public.tap_profiles t
  WHERE lower(t.slug) = lower(btrim(COALESCE(p_slug, '')))
    AND t.status = 'active'
    AND t.suspended_at IS NULL
  LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;

  v_tier := public.user_max_ui_tier(v_tap.user_id);
  v_pass := public.user_has_pass(v_tap.user_id);

  SELECT COALESCE(array_agg(e.key), '{}') INTO v_owned
  FROM public.entitlements e
  WHERE e.user_id = v_tap.user_id AND e.is_active AND e.type = 'customization';

  v_clamp := CASE
    WHEN public.tier_rank(v_tap.selected_ui_tier) <= public.tier_rank(v_tier)
      THEN public.canonical_experience(v_tap.selected_ui_tier)
    ELSE v_tier
  END;

  -- 024: the page's own tier includes its buttons; add-ons add more.
  v_shown := ARRAY(
    SELECT unnest(v_tap.enabled_customizations)
    INTERSECT
    SELECT unnest(v_owned || public.tier_buttons(v_clamp))
  );

  v_base := jsonb_build_object(
    'palette', CASE WHEN v_tap.theme_palette = ANY(public.theme_options('palette', v_clamp, v_pass)) THEN v_tap.theme_palette ELSE 'midnight' END,
    'layout', CASE WHEN v_tap.theme_layout = ANY(public.theme_options('layout', v_clamp, v_pass)) THEN v_tap.theme_layout ELSE 'classic' END,
    'buttons', CASE WHEN v_tap.theme_buttons = ANY(public.theme_options('buttons', v_clamp, v_pass)) THEN v_tap.theme_buttons ELSE 'solid' END,
    'font', CASE WHEN v_tap.theme_font = ANY(public.theme_options('font', v_clamp, v_pass)) THEN v_tap.theme_font ELSE 'sans' END,
    'animation', CASE WHEN v_tap.theme_animation = ANY(public.theme_options('animation', v_clamp, v_pass)) THEN v_tap.theme_animation ELSE 'auto' END
  );

  v_event := public.tap_event_theme_for(now());
  v_event_theme := COALESCE(v_event->'theme', '{}'::jsonb);

  -- Event styling is platform-controlled and applies globally while active.
  -- It is not a customer entitlement and must therefore not be filtered through
  -- theme_options(). The customer's saved theme remains in baseTheme.
  v_eff := jsonb_build_object(
    'palette', COALESCE(NULLIF(v_event_theme->>'palette',''), v_base->>'palette'),
    'layout', COALESCE(NULLIF(v_event_theme->>'layout',''), v_base->>'layout'),
    'buttons', COALESCE(NULLIF(v_event_theme->>'buttons',''), v_base->>'buttons'),
    'font', COALESCE(NULLIF(v_event_theme->>'font',''), v_base->>'font'),
    'animation', COALESCE(NULLIF(v_event_theme->>'animation',''), v_base->>'animation')
  );

  RETURN jsonb_build_object(
    'slug', v_tap.slug,
    'pageTemplate', v_tap.page_template,
    'experience', v_clamp,
    'displayName', v_tap.display_name,
    'headline', v_tap.headline,
    'designation', v_tap.designation,
    'company', v_tap.company,
    'bio', v_tap.bio,
    'avatarUrl', v_tap.avatar_url,
    'location', CASE WHEN 'location' = ANY(v_shown) THEN v_tap.location END,
    'phone', CASE WHEN 'phone' = ANY(v_shown) THEN v_tap.phone END,
    'whatsapp', CASE WHEN 'whatsapp' = ANY(v_shown) THEN v_tap.whatsapp END,
    'email', CASE WHEN 'email' = ANY(v_shown) THEN v_tap.email END,
    'website', CASE WHEN 'website' = ANY(v_shown) THEN v_tap.website END,
    'instagram', CASE WHEN 'instagram' = ANY(v_shown) THEN v_tap.instagram END,
    'linkedin', CASE WHEN 'linkedin' = ANY(v_shown) THEN v_tap.linkedin END,
    'youtube', CASE WHEN 'youtube' = ANY(v_shown) THEN v_tap.youtube END,
    'customLinks', CASE WHEN 'links' = ANY(v_shown) THEN v_tap.custom_links ELSE '[]'::jsonb END,
    'theme', v_eff,
    'baseTheme', v_base,
    'activeEvent', NULLIF(v_event, '{}'::jsonb)
  );
END;
$$;

"]

["-- Page families are independent of visual layout and physical card finish.
ALTER TABLE public.tap_profiles
  ADD COLUMN IF NOT EXISTS page_template TEXT
  CHECK (page_template IS NULL OR page_template IN ('business', 'restaurant', 'event', 'review'));

-- Let an authorised SHYGON administrator create an additional Tap page for an
-- existing customer. The customer owns and edits the page after creation.
-- A draft is used so an empty page is not published before the customer fills it.

-- Stop offering card finishes and add-ons the current website cannot sell.
-- Rows remain for references from old orders and reports.
UPDATE public.products
SET active = false
WHERE product_type = 'card'
  AND material = 'transparent'
  AND active IS DISTINCT FROM false;

UPDATE public.products
SET active = false
WHERE sku IN ('plan-pro', 'plan-3d', 'plan-custom', 'plan-lifetime', 'addon-gallery')
  AND active IS DISTINCT FROM false;

DROP FUNCTION IF EXISTS public.admin_create_tap_page(UUID, TEXT, TEXT, TEXT, TEXT);
DROP FUNCTION IF EXISTS public.admin_create_tap_page(UUID, TEXT, TEXT, TEXT, TEXT, TEXT);
CREATE FUNCTION public.admin_create_tap_page(
  p_user_id UUID,
  p_display_name TEXT,
  p_slug TEXT,
  p_page_template TEXT,
  p_layout TEXT,
  p_headline TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_admin UUID := public.require_admin('tap.moderate');
  v_name TEXT := NULLIF(btrim(COALESCE(p_display_name, '')), '');
  v_slug TEXT := lower(btrim(COALESCE(p_slug, '')));
  v_headline TEXT := NULLIF(btrim(COALESCE(p_headline, '')), '');
  v_tier TEXT;
  v_id UUID;
BEGIN
  IF p_user_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'Choose an existing customer.' USING ERRCODE = 'P0002';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id AND suspended_at IS NOT NULL) THEN
    RAISE EXCEPTION 'A Tap page cannot be created for a suspended customer.' USING ERRCODE = '22023';
  END IF;
  IF v_name IS NULL OR length(v_name) > 60 THEN
    RAISE EXCEPTION 'Enter a page name of 1–60 characters.' USING ERRCODE = '22023';
  END IF;
  IF v_headline IS NOT NULL AND length(v_headline) > 120 THEN
    RAISE EXCEPTION 'The short introduction must be 120 characters or fewer.' USING ERRCODE = '22023';
  END IF;
  IF v_slug !~ '^[a-z0-9][a-z0-9-]{2,39}$' THEN
    RAISE EXCEPTION 'The page address must be 3–40 lowercase letters, numbers, or hyphens.' USING ERRCODE = '22023';
  END IF;
  IF public.tap_slug_reserved(v_slug) THEN
    RAISE EXCEPTION 'That page address is reserved.' USING ERRCODE = '22023';
  END IF;
  IF public.tap_slug_taken(v_slug) THEN
    RAISE EXCEPTION 'That page address is already in use.' USING ERRCODE = '23505';
  END IF;

  v_tier := COALESCE(public.user_max_ui_tier(p_user_id), 'essential');
  IF p_page_template IS NULL OR p_page_template NOT IN ('business', 'restaurant', 'event', 'review') THEN
    RAISE EXCEPTION 'Choose a valid page template.' USING ERRCODE = '22023';
  END IF;
  IF p_layout IS NULL OR p_layout <> ALL (public.theme_options('layout', v_tier, public.user_has_pass(p_user_id))) THEN
    RAISE EXCEPTION 'This template is not available for the customer’s current Tap experience.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.tap_profiles (
    user_id, customer_id, slug, username, display_name, headline, email,
    status, published, published_at, selected_ui_tier, enabled_customizations,
    theme_layout, theme_palette, theme_buttons, theme_font, theme_animation, page_template
  )
  SELECT p.id, p.id, v_slug, v_slug, v_name, v_headline, p.email,
         'draft', false, NULL, v_tier, ARRAY[]::TEXT[], p_layout,
         'midnight', 'solid', 'sans', 'auto', p_page_template
  FROM public.profiles p
  WHERE p.id = p_user_id
  RETURNING id INTO v_id;

  INSERT INTO public.notifications (user_id, category, title, body, link, metadata)
  VALUES (
    p_user_id,
    'tap',
    'A new Tap page is ready to edit',
    'Your new page “' || v_name || '” is a draft. Add your details and publish it from your profile.',
    '/shygontap/tap',
    jsonb_build_object('tap_profile_id', v_id, 'slug', v_slug)
  );

  PERFORM public.admin_audit(
    v_admin,
    'tap.page_created',
    'tap',
    v_id::text,
    jsonb_build_object('user_id', p_user_id, 'slug', v_slug, 'page_template', p_page_template, 'layout', p_layout)
  );

  RETURN public.admin_get_tap(v_id);
END;
$$;

REVOKE ALL ON FUNCTION public.admin_create_tap_page(UUID, TEXT, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_create_tap_page(UUID, TEXT, TEXT, TEXT, TEXT, TEXT) TO authenticated, service_role;


-- Public renderer receives the selected page family through the existing
-- entitlement-clamped profile resolver.
CREATE OR REPLACE FUNCTION public.get_public_profile(p_slug TEXT)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_tap         public.tap_profiles%ROWTYPE;
  v_tier        TEXT;
  v_pass        BOOLEAN;
  v_owned       TEXT[];
  v_shown       TEXT[];
  v_clamp       TEXT;
  v_event       JSONB;
  v_event_theme JSONB;
  v_base        JSONB;
  v_eff         JSONB;
BEGIN
  SELECT * INTO v_tap
  FROM public.tap_profiles t
  WHERE lower(t.slug) = lower(btrim(COALESCE(p_slug, '')))
    AND t.status = 'active'
    AND t.suspended_at IS NULL
  LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;

  v_tier := public.user_max_ui_tier(v_tap.user_id);
  v_pass := public.user_has_pass(v_tap.user_id);

  SELECT COALESCE(array_agg(e.key), '{}') INTO v_owned
  FROM public.entitlements e
  WHERE e.user_id = v_tap.user_id AND e.is_active AND e.type = 'customization';

  v_clamp := CASE
    WHEN public.tier_rank(v_tap.selected_ui_tier) <= public.tier_rank(v_tier)
      THEN public.canonical_experience(v_tap.selected_ui_tier)
    ELSE v_tier
  END;

  -- 024: the page's own tier includes its buttons; add-ons add more.
  v_shown := ARRAY(
    SELECT unnest(v_tap.enabled_customizations)
    INTERSECT
    SELECT unnest(v_owned || public.tier_buttons(v_clamp))
  );

  v_base := jsonb_build_object(
    'palette', CASE WHEN v_tap.theme_palette = ANY(public.theme_options('palette', v_clamp, v_pass)) THEN v_tap.theme_palette ELSE 'midnight' END,
    'layout', CASE WHEN v_tap.theme_layout = ANY(public.theme_options('layout', v_clamp, v_pass)) THEN v_tap.theme_layout ELSE 'classic' END,
    'buttons', CASE WHEN v_tap.theme_buttons = ANY(public.theme_options('buttons', v_clamp, v_pass)) THEN v_tap.theme_buttons ELSE 'solid' END,
    'font', CASE WHEN v_tap.theme_font = ANY(public.theme_options('font', v_clamp, v_pass)) THEN v_tap.theme_font ELSE 'sans' END,
    'animation', CASE WHEN v_tap.theme_animation = ANY(public.theme_options('animation', v_clamp, v_pass)) THEN v_tap.theme_animation ELSE 'auto' END
  );

  v_event := public.tap_event_theme_for(now());
  v_event_theme := COALESCE(v_event->'theme', '{}'::jsonb);

  -- Event styling is platform-controlled and applies globally while active.
  -- It is not a customer entitlement and must therefore not be filtered through
  -- theme_options(). The customer's saved theme remains in baseTheme.
  v_eff := jsonb_build_object(
    'palette', COALESCE(NULLIF(v_event_theme->>'palette',''), v_base->>'palette'),
    'layout', COALESCE(NULLIF(v_event_theme->>'layout',''), v_base->>'layout'),
    'buttons', COALESCE(NULLIF(v_event_theme->>'buttons',''), v_base->>'buttons'),
    'font', COALESCE(NULLIF(v_event_theme->>'font',''), v_base->>'font'),
    'animation', COALESCE(NULLIF(v_event_theme->>'animation',''), v_base->>'animation')
  );

  RETURN jsonb_build_object(
    'slug', v_tap.slug,
    'pageTemplate', v_tap.page_template,
    'experience', v_clamp,
    'displayName', v_tap.display_name,
    'headline', v_tap.headline,
    'designation', v_tap.designation,
    'company', v_tap.company,
    'bio', v_tap.bio,
    'avatarUrl', v_tap.avatar_url,
    'location', CASE WHEN 'location' = ANY(v_shown) THEN v_tap.location END,
    'phone', CASE WHEN 'phone' = ANY(v_shown) THEN v_tap.phone END,
    'whatsapp', CASE WHEN 'whatsapp' = ANY(v_shown) THEN v_tap.whatsapp END,
    'email', CASE WHEN 'email' = ANY(v_shown) THEN v_tap.email END,
    'website', CASE WHEN 'website' = ANY(v_shown) THEN v_tap.website END,
    'instagram', CASE WHEN 'instagram' = ANY(v_shown) THEN v_tap.instagram END,
    'linkedin', CASE WHEN 'linkedin' = ANY(v_shown) THEN v_tap.linkedin END,
    'youtube', CASE WHEN 'youtube' = ANY(v_shown) THEN v_tap.youtube END,
    'customLinks', CASE WHEN 'links' = ANY(v_shown) THEN v_tap.custom_links ELSE '[]'::jsonb END,
    'theme', v_eff,
    'baseTheme', v_base,
    'activeEvent', NULLIF(v_event, '{}'::jsonb)
  );
END;
$$;

"]

["create table if not exists public.shygontap_profiles (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users(id) on delete cascade,
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  template_id text not null,
  template_name text not null,
  name text not null,
  title text not null default '',
  phone text not null default '',
  email text not null default '',
  description text not null default '',
  address text not null default '',
  website text not null default '',
  instagram text not null default '',
  facebook text not null default '',
  whatsapp text not null default '',
  photo_url text not null default '',
  published boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists shygontap_profiles_owner_created_idx on public.shygontap_profiles(owner_id, created_at desc);
create index if not exists shygontap_profiles_published_slug_idx on public.shygontap_profiles(slug) where published = true;
alter table public.shygontap_profiles enable row level security;
grant select on public.shygontap_profiles to anon, authenticated;
grant insert, update, delete on public.shygontap_profiles to authenticated;
drop policy if exists "Public can view published Shygon Tap profiles" on public.shygontap_profiles;
create policy "Public can view published Shygon Tap profiles" on public.shygontap_profiles for select to anon, authenticated using (published = true);
drop policy if exists "Owners can view their Shygon Tap profiles" on public.shygontap_profiles;
create policy "Owners can view their Shygon Tap profiles" on public.shygontap_profiles for select to authenticated using ((select auth.uid()) = owner_id);
drop policy if exists "Owners can create their Shygon Tap profiles" on public.shygontap_profiles;
create policy "Owners can create their Shygon Tap profiles" on public.shygontap_profiles for insert to authenticated with check ((select auth.uid()) = owner_id);
drop policy if exists "Owners can update their Shygon Tap profiles" on public.shygontap_profiles;
create policy "Owners can update their Shygon Tap profiles" on public.shygontap_profiles for update to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
drop policy if exists "Owners can delete their Shygon Tap profiles" on public.shygontap_profiles;
create policy "Owners can delete their Shygon Tap profiles" on public.shygontap_profiles for delete to authenticated using ((select auth.uid()) = owner_id);
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('shygontap-photos', 'shygontap-photos', true, 5242880, array['image/jpeg','image/png','image/webp','image/avif'])
on conflict (id) do update set public = true, file_size_limit = 5242880, allowed_mime_types = array['image/jpeg','image/png','image/webp','image/avif'];
drop policy if exists "Tap owners upload photos to their own folder" on storage.objects;
create policy "Tap owners upload photos to their own folder" on storage.objects for insert to authenticated with check (bucket_id = 'shygontap-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
drop policy if exists "Tap owners read their own photos" on storage.objects;
create policy "Tap owners read their own photos" on storage.objects for select to authenticated using (bucket_id = 'shygontap-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
drop policy if exists "Tap owners update their own photos" on storage.objects;
create policy "Tap owners update their own photos" on storage.objects for update to authenticated using (bucket_id = 'shygontap-photos' and (storage.foldername(name))[1] = (select auth.uid())::text) with check (bucket_id = 'shygontap-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create or replace function public.shygontap_set_updated_at()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;
drop trigger if exists shygontap_profiles_updated_at on public.shygontap_profiles;
create trigger shygontap_profiles_updated_at before update on public.shygontap_profiles for each row execute function public.shygontap_set_updated_at();"]
